26	// ---------------------------------------------------------------------------
27	// Tiling constants
28	// ---------------------------------------------------------------------------
29	
30	constexpr int32_t DEFAULT_BLOCK_M = 64;
31	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
32	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
33	
34	// ---------------------------------------------------------------------------
35	// Host function
36	// ---------------------------------------------------------------------------
37	
38	namespace ascend_kernel {
39	
40	std::vector<at::Tensor> add_rms_norm(
41	    const at::Tensor &x1, const at::Tensor &x2,
42	    const at::Tensor &gamma, double eps)
43	{
44	    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
45	                   x1.scalar_type() == at::kBFloat16,
46	        "x1 must be float16, float32, or bfloat16");
47	    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
48	        "x1 and x2 must have the same dtype");
49	    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
50	        "gamma must have the same dtype as x1/x2");
51	    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
52	    TORCH_CHECK(x1.sizes().back() == gamma.sizes()[0],
53	        "gamma shape mismatch: N_last=", x1.sizes().back(), " vs N_gamma=", gamma.sizes()[0]);
54	    TORCH_CHECK(x1.sizes() == x2.sizes(),
55	        "x1 and x2 must have the same shape");
56	
57	    // Flatten ND → 2D: M = product of all dims except last, N = last dim
58	    auto origShape = x1.sizes();
59	    int32_t N = static_cast<int32_t>(x1.sizes().back());
60	    int64_t M = x1.numel() / N;
61	
62	    at::Tensor x1_2d = x1.contiguous().view({M, N});
63	    at::Tensor x2_2d = x2.contiguous().view({M, N});
64	
65	    int32_t M_i32 = static_cast<int32_t>(M);
66	    int32_t mNum = (M_i32 + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
67	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
68	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
69	
70	    at::Tensor y = at::empty_like(x1_2d);
71	    at::Tensor rstd = at::empty({static_cast<int64_t>(M)}, x1_2d.options());
72	    at::Tensor x_add = at::empty_like(x1_2d);
73	
74	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
75	    int64_t dtypeFlag = 0;
76	    if (x1_2d.scalar_type() == at::kHalf) {
77	        dtypeFlag = 1;
78	    } else if (x1_2d.scalar_type() == at::kBFloat16) {
79	        dtypeFlag = 2;
80	    }
81	
82	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
83	    int32_t blockM = DEFAULT_BLOCK_M;
84	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
85	    float epsVal = static_cast<float>(eps);
86	    float invN = 1.0f / static_cast<float>(N);
87	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
88	
89	    // Use single_row strategy for all cases for now
90	    EXEC_KERNEL_CMD(add_rms_norm_single_row, blockDim,
91	                    x1_2d, x2_2d, gamma, y, rstd, x_add,
92	                    M_i32, N, blockM, usedCoreNum,
93	                    tasksPerCore, epsVal, invN, dtypeFlag);
94	
95	    // Reshape outputs back to original shape
96	    y = y.view(origShape);
97	    rstd = rstd.view(origShape.slice(0, origShape.size() - 1));
98	    x_add = x_add.view(origShape);
99	
100	    return {y, rstd, x_add};
101	}
