11	// AscendC AddRmsNorm kernel — fuses x_add = x1 + x2 with RMSNorm
12	// Strategies: merge_n (N <= 1024), single_row (1024 < N <= 8192), splitd (N > 8192)
13	// Supports float32, float16, bfloat16
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 1;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	template <typename T>
24	__aicore__ inline void LoadGmToUb(
25	    AscendC::LocalTensor<T> &dst,
26	    AscendC::GlobalTensor<T> src,
27	    uint32_t count)
28	{
29	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
30	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
31	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
32	}
33	
34	template <typename T>
35	__aicore__ inline void StoreUbToGm(
36	    AscendC::GlobalTensor<T> dst,
37	    AscendC::LocalTensor<T> &src,
38	    uint32_t count)
39	{
40	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
41	    AscendC::DataCopyPad(dst, src, copyParams);
42	}
43	
44	// ---------------------------------------------------------------------------
45	// Strategy-agnostic helpers
46	// ---------------------------------------------------------------------------
47	
48	template <typename T>
49	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
50	{
51	    if constexpr (std::is_same_v<T, bfloat16_t>) {
52	        return AscendC::RoundMode::CAST_ROUND;
53	    }
54	    return AscendC::RoundMode::CAST_NONE;
55	}
56	
57	template <typename T>
58	__aicore__ inline void PrepareInputTensor(
59	    AscendC::LocalTensor<float> &dst,
60	    AscendC::LocalTensor<T> &src,
61	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
62	    int32_t count)
63	{
64	    if constexpr (std::is_same_v<T, float>) {
65	        dst = src.template ReinterpretCast<float>();
66	    } else {
67	        dst = castBuf.Get<float>();
68	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
69	        AscendC::PipeBarrier<PIPE_V>();
70	    }
71	}
72	
73	template <typename T>
74	__aicore__ inline void PrepareOutputTensor(
75	    AscendC::LocalTensor<float> &dst,
76	    AscendC::LocalTensor<T> &out,
77	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
78	{
79	    if constexpr (std::is_same_v<T, float>) {
80	        dst = out.template ReinterpretCast<float>();
81	    } else {
82	        dst = castBuf.Get<float>();
83	    }
84	}
85	
86	template <typename T>
87	__aicore__ inline void FinalizeOutputTensor(
88	    AscendC::LocalTensor<T> &out,
89	    AscendC::LocalTensor<float> &src,
90	    int32_t count)
91	{
92	    if constexpr (!std::is_same_v<T, float>) {
93	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
94	        AscendC::PipeBarrier<PIPE_V>();
95	    }
96	}
