98	// =========================================================================
99	// Strategy 1: merge_n — N <= 1024, merge kMergeRowFactor rows into one tile
100	// =========================================================================
101	
102	template <typename dataType>
103	class AddRmsNormMergeNKernel {
104	public:
105	    __aicore__ inline void Init(
106	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR y, GM_ADDR rstd, GM_ADDR x_add,
107	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
108	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
109	    {
110	        this->M = M;
111	        this->N = N;
112	        this->blockM = blockM;
113	        this->usedCoreNum = usedCoreNum;
114	        this->tasksPerCore = tasksPerCore;
115	        this->rowFactor = rowFactor;
116	        this->eps = eps;
117	        this->invN = invN;
118	
119	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
120	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
121	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
122	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
123	        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstd), M);
124	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add), static_cast<uint64_t>(M) * N);
125	
126	        if ASCEND_IS_AIV { InitAivBuffers(); }
127	    }
128	
129	    __aicore__ inline void InitAivBuffers()
130	    {
131	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
132	        rowLoops_ = subBlockRows_ / rowFactor;
133	        pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
134	        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
135	        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
136	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
137	        pipe.InitBuffer(rstdOutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(dataType));
138	        pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
139	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
140	        pipe.InitBuffer(gammaTileBuf_, kMergeRowFactor * N * sizeof(float));
141	        pipe.InitBuffer(gammaBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
142	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
143	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
144	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
145	        pipe.InitBuffer(rstdBuf_, kMergeRowFactor * sizeof(float));
146	        if constexpr (!std::is_same_v<dataType, float>) {
147	            pipe.InitBuffer(x1CastBuf_, kMergeRowFactor * N * sizeof(float));
148	            pipe.InitBuffer(x2CastBuf_, kMergeRowFactor * N * sizeof(float));
149	            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
150	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
151	        }
152	
153	        // Pre-load gamma and broadcast to kMergeRowFactor rows
154	        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
155	        const uint32_t gammaDstShape[2] = {
156	            static_cast<uint32_t>(kMergeRowFactor),
157	            static_cast<uint32_t>(N),
158	        };
159	
160	        gammaInLocal_ = gammaBuf_.Get<dataType>();
161	        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
162	        AscendC::PipeBarrier<PIPE_MTE2>();
163	        AscendC::PipeBarrier<PIPE_ALL>();
164	        PrepareInputTensor<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
165	
166	        gammaTileLocal_ = gammaTileBuf_.Get<float>();
167	        gammaBroadcastTmpLocal_ = gammaBroadcastTmpBuf_.Get<uint8_t>();
168	        AscendC::PipeBarrier<PIPE_ALL>();
169	        AscendC::Broadcast<float, 2, 0>(
170	            gammaTileLocal_, gammaLocal_,
171	            gammaDstShape, gammaSrcShape,
172	            gammaBroadcastTmpLocal_);
173	        AscendC::PipeBarrier<PIPE_V>();
174	    }
175	
176	    __aicore__ inline void Process()
177	    {
178	        if ASCEND_IS_AIV {
179	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
180	            const int subBlockIdx = AscendC::GetSubBlockIdx();
181	
182	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
183	                const int bx = coreIdx * tasksPerCore + localIdx;
184	                if (bx >= (M + blockM - 1) / blockM) { continue; }
185	
186	                for (int r = 0; r < rowLoops_; ++r) {
187	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
188	                    const int validRows = M - rowBase;
189	                    if (validRows > 0) {
190	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
191	                    }
192	                }
193	            }
194	        }
195	    }
196	
197	private:
198	    static constexpr int kMergeRowFactor = 8;
199	
200	    __aicore__ inline void CopyInX1(int32_t rowBase, int32_t count)
201	    {
202	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
203	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
204	        x1InQueue_.EnQue(x1InLocal_);
205	    }
206	
207	    __aicore__ inline void CopyInX2(int32_t rowBase, int32_t count)
208	    {
209	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
210	        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
211	        x2InQueue_.EnQue(x2InLocal_);
212	    }
213	
214	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
215	    {
216	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
217	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
218	        yOutQueue_.FreeTensor(yOutLocal_);
219	    }
220	
221	    __aicore__ inline void CopyOutRstd(int32_t rowBase, int32_t count)
222	    {
223	        rstdOutLocal_ = rstdOutQueue_.DeQue<dataType>();
224	        StoreUbToGm(rstdGM_[rowBase], rstdOutLocal_, static_cast<uint32_t>(count));
225	        rstdOutQueue_.FreeTensor(rstdOutLocal_);
226	    }
227	
228	    __aicore__ inline void CopyOutXAdd(int32_t rowBase, int32_t count)
229	    {
230	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
231	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowBase) * N], xAddOutLocal_, static_cast<uint32_t>(count));
232	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
233	    }
234	
235	    __aicore__ inline void ComputeSingleRow()
236	    {
237	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
238	        const uint32_t scaleSrcShape[2] = {1U, 1U};
239	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
240	
241	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
242	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
243	        rstdOutLocal_ = rstdOutQueue_.AllocTensor<dataType>();
244	
245	        scaleLocal_ = scaleBuf_.Get<float>();
246	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
247	        sumLocal_ = sumBuf_.Get<float>();
248	        rstdLocal_ = rstdBuf_.Get<float>();
249	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
250	
251	        // DeQue x1, cast to float32
252	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
253	        PrepareInputTensor<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
254	
255	        // DeQue x2, cast to float32
256	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
257	        PrepareInputTensor<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
258	
259	        // x_add = x1 + x2 → yLocal_
260	        PrepareOutputTensor<dataType>(yLocal_, yOutLocal_, yCastBuf_);
261	        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
262	
263	        // Output x_add BEFORE RMSNorm modifies yLocal_
264	        FinalizeOutputTensor<dataType>(xAddOutLocal_, yLocal_, N);
265	
266	        // RMSNorm on yLocal_ (which holds x_add)
267	        // yLocal_^2 → reuse x1Local_ as temp (x1 is no longer needed after Add)
268	        AscendC::Mul(x1Local_, yLocal_, yLocal_, N);
269	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
270	            sumLocal_, x1Local_, reduceTmpLocal_, reduceShape, true);
271	
272	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
273	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
274	        AscendC::Rsqrt(rstdLocal_, sumLocal_, 1);
275	        FinalizeOutputTensor<dataType>(rstdOutLocal_, rstdLocal_, 1);
276	        AscendC::PipeBarrier<PIPE_V>();
277	
278	        AscendC::Broadcast<float, 2, 1>(
279	            scaleLocal_, rstdLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
280	
281	        // y = x_add * rstd * gamma
282	        AscendC::Mul(yLocal_, yLocal_, scaleLocal_, N);
283	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
284	        FinalizeOutputTensor<dataType>(yOutLocal_, yLocal_, N);
285	
286	        x1InQueue_.FreeTensor(x1InLocal_);
287	        x2InQueue_.FreeTensor(x2InLocal_);
288	        yOutQueue_.EnQue(yOutLocal_);
289	        rstdOutQueue_.EnQue(rstdOutLocal_);
290	        xAddOutQueue_.EnQue(xAddOutLocal_);
291	    }
292	
293	    __aicore__ inline void ComputeRows(int32_t tileSize)
294	    {
295	        const uint32_t reduceShape[2] = {
296	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
297	        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
298	        const uint32_t scaleDstShape[2] = {
299	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
300	
301	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
302	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
303	        rstdOutLocal_ = rstdOutQueue_.AllocTensor<dataType>();
304	
305	        // DeQue x1 and x2
306	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
307	        PrepareInputTensor<dataType>(x1Local_, x1InLocal_, x1CastBuf_, tileSize);
308	
309	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
310	        PrepareInputTensor<dataType>(x2Local_, x2InLocal_, x2CastBuf_, tileSize);
311	
312	        // x_add = x1 + x2 → yLocal_
313	        PrepareOutputTensor<dataType>(yLocal_, yOutLocal_, yCastBuf_);
314	        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);
315	
316	        // Output x_add BEFORE RMSNorm modifies yLocal_
317	        FinalizeOutputTensor<dataType>(xAddOutLocal_, yLocal_, tileSize);
318	
319	        // RMSNorm: yLocal_^2 → reuse x1Local_
320	        AscendC::Mul(x1Local_, yLocal_, yLocal_, tileSize);
321	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
322	            sumLocal_, x1Local_, reduceTmpLocal_, reduceShape, true);
323	
324	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
325	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
326	        AscendC::Rsqrt(rstdLocal_, sumLocal_, kMergeRowFactor);
327	        FinalizeOutputTensor<dataType>(rstdOutLocal_, rstdLocal_, kMergeRowFactor);
328	        AscendC::PipeBarrier<PIPE_V>();
329	
330	        AscendC::Broadcast<float, 2, 1>(
331	            scaleLocal_, rstdLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
332	
333	        // y = x_add * rstd * gamma
334	        AscendC::Mul(yLocal_, yLocal_, scaleLocal_, tileSize);
335	        AscendC::Mul(yLocal_, yLocal_, gammaTileLocal_, tileSize);
336	        FinalizeOutputTensor<dataType>(yOutLocal_, yLocal_, tileSize);
337	
338	        x1InQueue_.FreeTensor(x1InLocal_);
339	        x2InQueue_.FreeTensor(x2InLocal_);
340	        yOutQueue_.EnQue(yOutLocal_);
341	        rstdOutQueue_.EnQue(rstdOutLocal_);
342	        xAddOutQueue_.EnQue(xAddOutLocal_);
343	    }
344	
345	    __aicore__ inline void ProcessSingleRow(int rowIdx)
346	    {
347	        CopyInX1(rowIdx, N);
348	        CopyInX2(rowIdx, N);
349	        ComputeSingleRow();
350	        CopyOutRstd(rowIdx, 1);
351	        CopyOutXAdd(rowIdx, N);
352	        CopyOutY(rowIdx, N);
353	    }
354	
355	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
356	    {
357	        if (validRows < kMergeRowFactor) {
358	            for (int r = 0; r < validRows; ++r) {
359	                ProcessSingleRow(rowBase + r);
360	            }
361	            return;
362	        }
363	
364	        const int tileSize = kMergeRowFactor * N;
365	        CopyInX1(rowBase, tileSize);
366	        CopyInX2(rowBase, tileSize);
367	        ComputeRows(tileSize);
368	        CopyOutRstd(rowBase, validRows);
369	        CopyOutXAdd(rowBase, tileSize);
370	        CopyOutY(rowBase, tileSize);
371	    }
