432	// Strategy 2: single_row — 1024 < N <= 8192
433	// =========================================================================
434	
435	template <typename dataType>
436	class AddRmsNormSingleRowKernel {
437	public:
438	    __aicore__ inline void Init(
439	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR y, GM_ADDR rstd, GM_ADDR x_add,
440	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
441	        int32_t tasksPerCore, float eps, float invN)
442	    {
443	        this->M = M;
444	        this->N = N;
445	        this->blockM = blockM;
446	        this->usedCoreNum = usedCoreNum;
447	        this->tasksPerCore = tasksPerCore;
448	        this->eps = eps;
449	        this->invN = invN;
450	
451	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
452	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
453	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
454	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
455	        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstd), M);
456	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add), static_cast<uint64_t>(M) * N);
457	
458	        if ASCEND_IS_AIV {
459	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
460	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
461	            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
462	            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
463	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
464	            pipe.InitBuffer(rstdOutQueue_, BUFFER_NUM, sizeof(dataType));
465	            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
466	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
467	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
468	            pipe.InitBuffer(rstdBuf_, sizeof(float));
469	            if constexpr (!std::is_same_v<dataType, float>) {
470	                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
471	                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
472	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
473	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
474	            }
475	
476	            gammaInLocal_ = gammaBuf_.Get<dataType>();
477	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
478	            AscendC::PipeBarrier<PIPE_MTE2>();
479	            AscendC::PipeBarrier<PIPE_ALL>();
480	            PrepareInputTensor<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
481	        }
482	    }
483	
484	    __aicore__ inline void Process()
485	    {
486	        if ASCEND_IS_AIV {
487	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
488	            const int subBlockIdx = AscendC::GetSubBlockIdx();
489	            const int mNum = (M + blockM - 1) / blockM;
490	
491	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
492	                const int bx = coreIdx * tasksPerCore + localIdx;
493	                if (bx >= mNum) { continue; }
494	                for (int row = 0; row < subBlockRows_; ++row) {
495	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
496	                    if (rowIdx < M) { ProcessRow(rowIdx); }
497	                }
498	            }
499	        }
500	    }
501	
502	private:
503	    __aicore__ inline void CopyInX1(int32_t rowIdx)
504	    {
505	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
506	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
507	        x1InQueue_.EnQue(x1InLocal_);
508	    }
509	
510	    __aicore__ inline void CopyInX2(int32_t rowIdx)
511	    {
512	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
513	        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
514	        x2InQueue_.EnQue(x2InLocal_);
515	    }
516	
517	    __aicore__ inline void CopyOutY(int32_t rowIdx)
518	    {
519	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
520	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
521	        yOutQueue_.FreeTensor(yOutLocal_);
522	    }
523	
524	    __aicore__ inline void CopyOutRstd(int32_t rowIdx)
525	    {
526	        rstdOutLocal_ = rstdOutQueue_.DeQue<dataType>();
527	        StoreUbToGm(rstdGM_[rowIdx], rstdOutLocal_, 1);
528	        rstdOutQueue_.FreeTensor(rstdOutLocal_);
529	    }
530	
531	    __aicore__ inline void CopyOutXAdd(int32_t rowIdx)
532	    {
533	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
534	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowIdx) * N], xAddOutLocal_, static_cast<uint32_t>(N));
535	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
536	    }
537	
538	    __aicore__ inline void ComputeRow()
539	    {
540	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
541	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
542	        rstdOutLocal_ = rstdOutQueue_.AllocTensor<dataType>();
543	
544	        reduceLocal_ = reduceBuf_.Get<float>();
545	        sumLocal_ = sumBuf_.Get<float>();
546	        rstdLocal_ = rstdBuf_.Get<float>();
547	
548	        // DeQue x1, cast to float32
549	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
550	        PrepareInputTensor<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
551	
552	        // DeQue x2, cast to float32
553	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
554	        PrepareInputTensor<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
555	
556	        // x_add = x1 + x2 → yLocal_
557	        PrepareOutputTensor<dataType>(yLocal_, yOutLocal_, yCastBuf_);
558	        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
559	
560	        // RMSNorm: yLocal_^2 → reuse x2Local_
561	        AscendC::Mul(x2Local_, yLocal_, yLocal_, N);
562	        AscendC::ReduceSum<float>(sumLocal_, x2Local_, reduceLocal_, N);
563	
564	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
565	        AscendC::Duplicate(sumLocal_, meanSq, 1);
566	        AscendC::Rsqrt(rstdLocal_, sumLocal_, 1);
567	        AscendC::PipeBarrier<PIPE_ALL>();
568	        float invRmsVal = rstdLocal_.GetValue(0);
569	        AscendC::PipeBarrier<PIPE_ALL>();
570	        FinalizeOutputTensor<dataType>(rstdOutLocal_, rstdLocal_, 1);
571	
572	        // y = x_add * rstd * gamma
573	        AscendC::Muls(yLocal_, yLocal_, invRmsVal, N);
574	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
575	        FinalizeOutputTensor<dataType>(yOutLocal_, yLocal_, N);
576	
577	        // Output x_add
578	        FinalizeOutputTensor<dataType>(xAddOutLocal_, yLocal_, N);
579	
580	        x1InQueue_.FreeTensor(x1InLocal_);
581	        x2InQueue_.FreeTensor(x2InLocal_);
582	        yOutQueue_.EnQue(yOutLocal_);
583	        rstdOutQueue_.EnQue(rstdOutLocal_);
584	        xAddOutQueue_.EnQue(xAddOutLocal_);
585	    }
586	
587	    __aicore__ inline void ProcessRow(int rowIdx)
588	    {
589	        CopyInX1(rowIdx);
590	        CopyInX2(rowIdx);
591	        ComputeRow();
592	        CopyOutRstd(rowIdx);
593	        CopyOutXAdd(rowIdx);
594	        CopyOutY(rowIdx);
595	    }
596	
597	private:
598	    int32_t M = 0;
599	    int32_t N = 0;
600	    int32_t blockM = 0;
601	    int32_t usedCoreNum = 0;
602	    int32_t tasksPerCore = 0;
603	    float eps = 0.0f;
604	    float invN = 0.0f;
605	    int subBlockRows_ = 0;
606	
607	    AscendC::TPipe pipe;
608	    AscendC::GlobalTensor<dataType> x1GM_;
609	    AscendC::GlobalTensor<dataType> x2GM_;
610	    AscendC::GlobalTensor<dataType> gammaGM_;
611	    AscendC::GlobalTensor<dataType> yGM_;
612	    AscendC::GlobalTensor<dataType> rstdGM_;
613	    AscendC::GlobalTensor<dataType> xAddGM_;
614	
615	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
616	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
617	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
618	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> rstdOutQueue_;
619	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
620	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
