625	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
626	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
627	    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdBuf_;
628	
629	    AscendC::LocalTensor<dataType> x1InLocal_;
630	    AscendC::LocalTensor<dataType> x2InLocal_;
631	    AscendC::LocalTensor<dataType> yOutLocal_;
632	    AscendC::LocalTensor<dataType> rstdOutLocal_;
633	    AscendC::LocalTensor<dataType> xAddOutLocal_;
