710	private:
711	    static constexpr int kBlockN = 1024;
712	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
713	
714	    __aicore__ inline int32_t NumTiles() const
715	    {
716	        return (N + kBlockN - 1) / kBlockN;
717	    }
718	
719	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
720	    {
721	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
722	    }
723	
724	    __aicore__ inline void CopyInX1(int32_t rowIdx, int32_t colBase, int32_t validN)
725	    {
726	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
727	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
728	        x1InQueue_.EnQue(x1InLocal_);
729	    }
730	
731	    __aicore__ inline void CopyInX2(int32_t rowIdx, int32_t colBase, int32_t validN)
732	    {
733	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
734	        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
735	        x2InQueue_.EnQue(x2InLocal_);
736	    }
737	
738	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
739	    {
740	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
741	        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
742	        gammaInQueue_.EnQue(gammaInLocal_);
743	    }
744	
745	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
746	    {
747	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
748	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
749	        yOutQueue_.FreeTensor(yOutLocal_);
750	    }
751	
752	    __aicore__ inline void CopyOutRstd(int32_t rowIdx)
753	    {
754	        rstdOutLocal_ = rstdOutQueue_.DeQue<dataType>();
755	        StoreUbToGm(rstdGM_[rowIdx], rstdOutLocal_, 1);
756	        rstdOutQueue_.FreeTensor(rstdOutLocal_);
757	    }
758	
759	    __aicore__ inline void CopyOutXAdd(int32_t rowIdx, int32_t colBase, int32_t validN)
760	    {
761	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
762	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowIdx) * N + colBase], xAddOutLocal_, static_cast<uint32_t>(validN));
763	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
764	    }
765	
766	    // Pass 1: iterate tiles along N, accumulate sum(x_add^2)
767	    __aicore__ inline float ComputeRstd(int32_t rowIdx)
768	    {
769	        reduceLocal_ = reduceBuf_.Get<float>();
770	        sumLocal_ = sumBuf_.Get<float>();
771	        tempLocal_ = tempBuf_.Get<float>();
772	        rstdOutLocal_ = rstdOutQueue_.AllocTensor<dataType>();
773	        rstdLocal_ = rstdBuf_.Get<float>();
774	        float sumSq = 0.0f;
775	
776	        for (int by = 0; by < NumTiles(); ++by) {
777	            const int colBase = by * kBlockN;
778	            const int validN = GetValidN(colBase);
779	
780	            CopyInX1(rowIdx, colBase, validN);
781	            CopyInX2(rowIdx, colBase, validN);
782	
783	            x1InLocal_ = x1InQueue_.DeQue<dataType>();
784	            PrepareInputTensor<dataType>(x1Local_, x1InLocal_, x1CastBuf_, validN);
785	            x2InLocal_ = x2InQueue_.DeQue<dataType>();
786	            PrepareInputTensor<dataType>(x2Local_, x2InLocal_, x2CastBuf_, validN);
787	
788	            // x_add = x1 + x2
789	            AscendC::Add(tempLocal_, x1Local_, x2Local_, validN);
790	
791	            // Store x_add to GM
792	            xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
793	            FinalizeOutputTensor<dataType>(xAddOutLocal_, tempLocal_, validN);
794	            xAddOutQueue_.EnQue(xAddOutLocal_);
795	            CopyOutXAdd(rowIdx, colBase, validN);
796	
797	            // x_add^2 → reduce, accumulate
798	            AscendC::Mul(tempLocal_, tempLocal_, tempLocal_, validN);
799	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
800	            sumSq += sumLocal_.GetValue(0);
801	
802	            x1InQueue_.FreeTensor(x1InLocal_);
803	            x2InQueue_.FreeTensor(x2InLocal_);
804	        }
805	
806	        float meanSq = sumSq * invN + eps;
807	        AscendC::Duplicate(sumLocal_, meanSq, 1);
808	        AscendC::Rsqrt(rstdLocal_, sumLocal_, 1);
809	        AscendC::PipeBarrier<PIPE_ALL>();
810	        float invRmsVal = rstdLocal_.GetValue(0);
811	        AscendC::PipeBarrier<PIPE_ALL>();
812	        FinalizeOutputTensor<dataType>(rstdOutLocal_, rstdLocal_, 1);
813	
814	        rstdOutQueue_.EnQue(rstdOutLocal_);
815	        return invRmsVal;
816	    }
817	
818	    // Pass 2: apply normalization tile by tile
819	    __aicore__ inline void ComputeTile(float invRmsVal, int32_t rowIdx, int32_t colBase, int32_t validN)
820	    {
821	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
822	
823	        CopyInX1(rowIdx, colBase, validN);
824	        CopyInX2(rowIdx, colBase, validN);
825	        CopyInGamma(colBase, validN);
826	
827	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
828	        PrepareInputTensor<dataType>(x1Local_, x1InLocal_, x1CastBuf_, validN);
829	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
830	        PrepareInputTensor<dataType>(x2Local_, x2InLocal_, x2CastBuf_, validN);
831	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
832	        PrepareInputTensor<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
833	
834	        PrepareOutputTensor<dataType>(yLocal_, yOutLocal_, yCastBuf_);
835	        // y = (x1 + x2) * rstd * gamma
836	        AscendC::Add(yLocal_, x1Local_, x2Local_, validN);
837	        AscendC::Muls(yLocal_, yLocal_, invRmsVal, validN);
838	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
839	        FinalizeOutputTensor<dataType>(yOutLocal_, yLocal_, validN);
840	
841	        x1InQueue_.FreeTensor(x1InLocal_);
842	        x2InQueue_.FreeTensor(x2InLocal_);
843	        gammaInQueue_.FreeTensor(gammaInLocal_);
844	        yOutQueue_.EnQue(yOutLocal_);
845	    }
846	
847	    __aicore__ inline void ProcessRow(int rowIdx)
848	    {
849	        float invRmsVal = ComputeRstd(rowIdx);
850	        CopyOutRstd(rowIdx);
851	
852	        for (int by = 0; by < NumTiles(); ++by) {
853	            const int colBase = by * kBlockN;
854	            const int validN = GetValidN(colBase);
855	            ComputeTile(invRmsVal, rowIdx, colBase, validN);
856	            CopyOutY(rowIdx, colBase, validN);
857	        }
858	    }
859	
860	private:
861	    int32_t M = 0;
862	    int32_t N = 0;
863	    int32_t blockM = 0;
864	    int32_t usedCoreNum = 0;
865	    int32_t tasksPerCore = 0;
866	    float eps = 0.0f;
867	    float invN = 0.0f;
868	    int subBlockRows_ = 0;
869	
870	    AscendC::TPipe pipe;
871	    AscendC::GlobalTensor<dataType> x1GM_;
872	    AscendC::GlobalTensor<dataType> x2GM_;
873	    AscendC::GlobalTensor<dataType> gammaGM_;
874	    AscendC::GlobalTensor<dataType> yGM_;
875	    AscendC::GlobalTensor<dataType> rstdGM_;
876	    AscendC::GlobalTensor<dataType> xAddGM_;
877	
878	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
879	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
880	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
881	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
882	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> rstdOutQueue_;
883	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
884	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
885	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
886	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
887	    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdBuf_;
888	    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
889	    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
890	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
891	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
892	
893	    AscendC::LocalTensor<dataType> x1InLocal_;
894	    AscendC::LocalTensor<dataType> x2InLocal_;
895	    AscendC::LocalTensor<dataType> gammaInLocal_;
896	    AscendC::LocalTensor<dataType> yOutLocal_;
897	    AscendC::LocalTensor<dataType> rstdOutLocal_;
898	    AscendC::LocalTensor<dataType> xAddOutLocal_;
899	    AscendC::LocalTensor<float> rstdLocal_;
900	    AscendC::LocalTensor<float> x1Local_;
901	    AscendC::LocalTensor<float> x2Local_;
902	    AscendC::LocalTensor<float> gammaLocal_;
903	    AscendC::LocalTensor<float> yLocal_;
904	    AscendC::LocalTensor<float> reduceLocal_;
905	    AscendC::LocalTensor<float> sumLocal_;
906	    AscendC::LocalTensor<float> tempLocal_;
907	};
908	
909	// =========================================================================
910	// Shared dtype-dispatch helper
911	// =========================================================================
912	
913	template <template <typename> class Kernel, typename... ExtraArgs>
914	__aicore__ inline void DispatchAddRmsNorm(
915	    GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR y, GM_ADDR rstd, GM_ADDR x_add,
916	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
917	    int32_t tasksPerCore, float eps, float invN,
918	    int64_t dtypeFlag, ExtraArgs... extraArgs)
919	{
920	    if (dtypeFlag == 0) {
921	        Kernel<float> kernel;
922	        kernel.Init(x1, x2, gamma, y, rstd, x_add, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
923	        kernel.Process();
924	    } else if (dtypeFlag == 1) {
925	        Kernel<half> kernel;
926	        kernel.Init(x1, x2, gamma, y, rstd, x_add, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
927	        kernel.Process();
928	    } else {
929	        Kernel<bfloat16_t> kernel;
930	        kernel.Init(x1, x2, gamma, y, rstd, x_add, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
931	        kernel.Process();
932	    }
933	}
934	
935	// =========================================================================
936	// Kernel entry points — one per strategy with dtype dispatch
937	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
938	// =========================================================================
939	
940	extern "C" __global__ __aicore__ void add_rms_norm_merge_n(
941	    GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR y, GM_ADDR rstd, GM_ADDR x_add,
942	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
