// AscendC AscendQuantV2 kernel
// Performs quantized inference: x * scale [* scale if sqrt_mode] + offset → round → clip → int8
// Tile along N dimension, each block processes block_M rows

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(AscendC::LocalTensor<T> &dst,
                                  AscendC::GlobalTensor<T> src,
                                  uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(AscendC::GlobalTensor<T> dst,
                                    AscendC::LocalTensor<T> &src,
                                    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// Map round_mode int → AscendC Cast RoundMode
__aicore__ inline AscendC::RoundMode GetRoundMode(int64_t roundModeFlag)
{
    // 0=round(RINT), 1=floor, 2=ceil, 3=trunc
    if (roundModeFlag == 0) { return AscendC::RoundMode::CAST_RINT; }
    if (roundModeFlag == 1) { return AscendC::RoundMode::CAST_FLOOR; }
    if (roundModeFlag == 2) { return AscendC::RoundMode::CAST_CEIL; }
    return AscendC::RoundMode::CAST_TRUNC; // 3
}

// =========================================================================
// AscendQuantV2 Kernel  (template parameter SQRT_MODE controls double scale)
// =========================================================================

template <typename dataType, bool SQRT_MODE>
class AscendQuantV2Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR scale, GM_ADDR offset, GM_ADDR y,
        int32_t M, int32_t N, int32_t blockM, int32_t blockN,
        int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t roundModeFlag, bool perChannel)
    {
        this->M_ = M;
        this->N_ = N;
        this->blockM_ = blockM;
        this->blockN_ = blockN;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->roundModeFlag_ = roundModeFlag;
        this->perChannel_ = perChannel;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(scale), N);
        offsetGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(offset), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        const int32_t tileElems = blockM_ * blockN_;
        const int32_t scaleElems = blockN_;

        // Input queues (typed)
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
        pipe_.InitBuffer(scaleInQueue_, BUFFER_NUM, scaleElems * sizeof(dataType));
        pipe_.InitBuffer(offsetInQueue_, BUFFER_NUM, scaleElems * sizeof(dataType));
        // Output queue (int8)
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));

        // Compute buffers (float32)
        pipe_.InitBuffer(xBuf_, tileElems * sizeof(float));
        pipe_.InitBuffer(scaleBuf_, scaleElems * sizeof(float));
        pipe_.InitBuffer(scaleBroadBuf_, tileElems * sizeof(float));
        pipe_.InitBuffer(offsetBuf_, scaleElems * sizeof(float));
        pipe_.InitBuffer(offsetBroadBuf_, tileElems * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, tileElems * sizeof(float));
        pipe_.InitBuffer(clipBuf_, tileElems * sizeof(float));

        // Broadcast tmp (2 * tileElems uint8)
        pipe_.InitBuffer(bcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));

        // Cast buffers for fp16/bf16
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(xCastBuf_, tileElems * sizeof(float));
            pipe_.InitBuffer(scaleCastBuf_, scaleElems * sizeof(float));
            pipe_.InitBuffer(offsetCastBuf_, scaleElems * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();
            const int subBlockRows = blockM_ / AscendC::GetSubBlockNum();
            const int mNum = (M_ + blockM_ - 1) / blockM_;
            const int nNum = (N_ + blockN_ - 1) / blockN_;

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                const int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) { continue; }
                for (int row = 0; row < subBlockRows; ++row) {
                    const int rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
                    if (rowIdx >= M_) { continue; }
                    ProcessRow(rowIdx, nNum);
                }
            }
        }
    }

private:
    static constexpr int kRowFactor = 1; // process one row at a time

    __aicore__ inline void ProcessRow(int rowIdx, int nNum)
    {
        for (int nTile = 0; nTile < nNum; ++nTile) {
            int colBase = nTile * blockN_;
            int validN = (colBase + blockN_ <= N_) ? blockN_ : (N_ - colBase);
            int tileElems = kRowFactor * validN;

            CopyIn(rowIdx, colBase, validN);
            Compute(validN);
            CopyOut(rowIdx, colBase, validN);
        }
    }

    __aicore__ inline void CopyIn(int rowIdx, int colBase, int validN)
    {
        // Load x tile
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_ + colBase],
                   static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);

        // Load scale tile
        scaleInLocal_ = scaleInQueue_.AllocTensor<dataType>();
        LoadGmToUb(scaleInLocal_, scaleGM_[colBase],
                   static_cast<uint32_t>(validN));
        scaleInQueue_.EnQue(scaleInLocal_);

        // Load offset tile
        offsetInLocal_ = offsetInQueue_.AllocTensor<dataType>();
        LoadGmToUb(offsetInLocal_, offsetGM_[colBase],
                   static_cast<uint32_t>(validN));
        offsetInQueue_.EnQue(offsetInLocal_);
    }

    __aicore__ inline void CopyOut(int rowIdx, int colBase, int validN)
    {
        yOutLocal_ = yOutQueue_.DeQue<int8_t>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N_ + colBase],
                    yOutLocal_, static_cast<uint32_t>(validN));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void Compute(int validN)
    {
        // Allocate output tensor
        yOutLocal_ = yOutQueue_.AllocTensor<int8_t>();

        // Get compute buffers
        xLocal_ = xBuf_.Get<float>();
        scaleLocal_ = scaleBuf_.Get<float>();
        scaleBroadLocal_ = scaleBroadBuf_.Get<float>();
        offsetLocal_ = offsetBuf_.Get<float>();
        offsetBroadLocal_ = offsetBroadBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();
        clipLocal_ = clipBuf_.Get<float>();
        bcastTmp_ = bcastTmpBuf_.Get<uint8_t>();

        // ---- DeQue inputs and cast to float32 ----
        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInput(xLocal_, xInLocal_, validN);

        scaleInLocal_ = scaleInQueue_.DeQue<dataType>();
        PrepareScale(scaleLocal_, scaleInLocal_, validN);

        offsetInLocal_ = offsetInQueue_.DeQue<dataType>();
        PrepareOffset(offsetLocal_, offsetInLocal_, validN);

        // ---- Compute: tmp = x * scale ----
        if (perChannel_) {
            // Broadcast scale [1, N] → [1, N] (already row-shape, use as-is)
            // Since we process 1 row, no broadcast needed: scaleLocal_ is [validN]
            AscendC::Mul(tmpLocal_, xLocal_, scaleLocal_, validN);
        } else {
            // Per-tensor: scale is a single scalar
            float scaleVal = scaleLocal_.GetValue(0);
            AscendC::Muls(tmpLocal_, xLocal_, scaleVal, validN);
        }

        // ---- Compute: if sqrt_mode, tmp = tmp * scale ----
        if constexpr (SQRT_MODE) {
            if (perChannel_) {
                AscendC::Mul(tmpLocal_, tmpLocal_, scaleLocal_, validN);
            } else {
                float scaleVal = scaleLocal_.GetValue(0);
                AscendC::Muls(tmpLocal_, tmpLocal_, scaleVal, validN);
            }
        }

        // ---- Compute: tmp = tmp + offset ----
        if (perChannel_) {
            AscendC::Add(tmpLocal_, tmpLocal_, offsetLocal_, validN);
        } else {
            // Per-tensor: offset is a scalar; add it inline
            float offVal = offsetLocal_.GetValue(0);
            AscendC::Adds(tmpLocal_, tmpLocal_, offVal, validN);
        }

        // ---- Compute: clip to [-128, 127] ----
        AscendC::Maxs(clipLocal_, tmpLocal_, -128.0f, validN);
        AscendC::Mins(tmpLocal_, clipLocal_, 127.0f, validN);

        // ---- Compute: cast float32 → int8 with rounding ----
        AscendC::RoundMode roundMode = GetRoundMode(roundModeFlag_);
        AscendC::Cast(yOutLocal_, tmpLocal_, roundMode, validN);
        AscendC::PipeBarrier<PIPE_V>();

        // ---- Free input tensors and enque output ----
        xInQueue_.FreeTensor(xInLocal_);
        scaleInQueue_.FreeTensor(scaleInLocal_);
        offsetInQueue_.FreeTensor(offsetInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    // ---- Typed → float32 cast helpers ----

    __aicore__ inline void PrepareInput(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> castBuf = xCastBuf_.Get<float>();
            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            dst = castBuf;
        }
    }

    __aicore__ inline void PrepareScale(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> castBuf = scaleCastBuf_.Get<float>();
            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            dst = castBuf;
        }
    }

    __aicore__ inline void PrepareOffset(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> castBuf = offsetCastBuf_.Get<float>();
            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            dst = castBuf;
        }
    }

private:
    int32_t M_ = 0;
    int32_t N_ = 0;
    int32_t blockM_ = 0;
    int32_t blockN_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    int64_t roundModeFlag_ = 0;
    bool perChannel_ = false;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> scaleGM_;
    AscendC::GlobalTensor<dataType> offsetGM_;
    AscendC::GlobalTensor<int8_t> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> scaleInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> offsetInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBroadBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> clipBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> scaleInLocal_;
    AscendC::LocalTensor<dataType> offsetInLocal_;
    AscendC::LocalTensor<int8_t> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> scaleLocal_;
    AscendC::LocalTensor<float> scaleBroadLocal_;
    AscendC::LocalTensor<float> offsetLocal_;
    AscendC::LocalTensor<float> offsetBroadLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
    AscendC::LocalTensor<float> clipLocal_;
    AscendC::LocalTensor<uint8_t> bcastTmp_;
};

// =========================================================================
// Dtype-dispatch helper
// =========================================================================

template <bool SQRT_MODE>
__aicore__ inline void DispatchAscendQuantV2(
    GM_ADDR x, GM_ADDR scale, GM_ADDR offset, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t blockN,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t roundModeFlag, bool perChannel,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        AscendQuantV2Kernel<float, SQRT_MODE> kernel;
        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        AscendQuantV2Kernel<half, SQRT_MODE> kernel;
        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
        kernel.Process();
    } else {
        AscendQuantV2Kernel<bfloat16_t, SQRT_MODE> kernel;
        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
        kernel.Process();
    }
}

