// AscendQuantV2 op_host — input validation, tiling, kernel launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_ascend_quant_v2_without_sqrt.h"
#include "aclrtlaunch_ascend_quant_v2_with_sqrt.h"

namespace ascend_kernel {

// Tiling constants
constexpr int32_t DEFAULT_BLOCK_M = 1;   // process 1 row per tile for simplicity
constexpr int32_t DEFAULT_BLOCK_N = 256;  // tile along N dimension
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// Map round_mode string to flag: 0=RINT, 1=FLOOR, 2=CEIL, 3=TRUNC
static int64_t RoundModeToFlag(const std::string &rm) {
    if (rm == "round") return 0;
    if (rm == "floor") return 1;
    if (rm == "ceil")  return 2;
    if (rm == "trunc") return 3;
    return 0; // default to round
}

at::Tensor ascend_quant_v2(
    const at::Tensor &x,
    const at::Tensor &scale,
    const at::Tensor &offset,
    int64_t sqrt_mode_i64,
    int64_t round_mode_flag,
    int64_t per_channel_i64)
{
    // ---- Input validation ----
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(scale.scalar_type() == x.scalar_type(),
        "scale must have the same dtype as x");
    TORCH_CHECK(offset.scalar_type() == x.scalar_type(),
        "offset must have the same dtype as x");
    TORCH_CHECK(x.dim() >= 2, "x must have at least 2 dimensions");

    // ---- Flatten to 2D ----
    auto origShape = x.sizes();
    int32_t N = static_cast<int32_t>(x.sizes().back());
    int64_t M = x.numel() / N;

    at::Tensor x_2d = x.contiguous().view({M, N});
    at::Tensor scale_1d = scale.reshape({N}).contiguous();
    at::Tensor offset_1d = offset.reshape({N}).contiguous();

    // ---- Tiling computation ----
    int32_t M_i32 = static_cast<int32_t>(M);
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t blockN = DEFAULT_BLOCK_N;
    int32_t mNum = (M_i32 + blockM - 1) / blockM;

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    int32_t usedCoreNum = std::min<int32_t>(
        DEFAULT_NUM_PHYSICAL_CORES,
        std::max<int32_t>(1, std::min(mNum, coreNum)));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Create int8 output tensor
    at::Tensor y = at::empty({M, N}, x.options().dtype(at::kByte));

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x_2d.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x_2d.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t _M = M_i32;
    int32_t _N = N;
    int32_t _blockM = blockM;
    int32_t _blockN = blockN;
    int32_t _usedCoreNum = usedCoreNum;
    int32_t _tasksPerCore = tasksPerCore;
    int64_t _roundModeFlag = round_mode_flag;
    int64_t _perChannelI64 = per_channel_i64;
    int64_t _dtypeFlag = dtypeFlag;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    bool sqrtMode = (sqrt_mode_i64 != 0);

    // Dispatch to sqrt or non-sqrt kernel entry
    if (sqrtMode) {
        EXEC_KERNEL_CMD(ascend_quant_v2_with_sqrt, blockDim,
                        x_2d, scale_1d, offset_1d, y,
                        _M, _N, _blockM, _blockN,
                        _usedCoreNum, _tasksPerCore,
                        _roundModeFlag, _perChannelI64, _dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(ascend_quant_v2_without_sqrt, blockDim,
                        x_2d, scale_1d, offset_1d, y,
                        _M, _N, _blockM, _blockN,
                        _usedCoreNum, _tasksPerCore,
                        _roundModeFlag, _perChannelI64, _dtypeFlag);
    }

    // Reshape output back to original shape
    y = y.view(origShape);
    return y;
}

}  // namespace ascend_kernel
